import {
  getLocalSolvedPuzzleMap,
  PuzzleInfoBox,
  ClickableMonarchDevice,
} from "@hunt/puzzle-components";

const CAPSTONE_SLUG = "filial_pie_tree";

const PuzzleComponent = () => {
  const solvedPuzzles = getLocalSolvedPuzzleMap();

  return CAPSTONE_SLUG in solvedPuzzles ? (
    <div className="flex items-center gap-2">
      The Royal Groves Puzzmon are looking to redecorate. Can you design a place
      that optimizes their needs and preferences?
      <ClickableMonarchDevice zoneSlug="royal_groves" className="w-20" />,
    </div>
  ) : (
    <PuzzleInfoBox copyable={false}>
      You need to solve the{" "}
      <a href={`/puzzles/${CAPSTONE_SLUG}`}>Royal Groves capstone puzzle</a>{" "}
      before you can access this task.
    </PuzzleInfoBox>
  );
};

export default PuzzleComponent;
